import math
from itertools import combinations
from sympy import primerange, primepi
def rhs(x):
    ps=list(primerange(2,math.isqrt(x)+1)); tot=0
    for k in range(len(ps)+1):
        for c in combinations(ps,k):
            tot+=(-1)**k*(x//math.prod(c))
    return tot
for x in range(1,601):
    assert rhs(x)==primepi(x)-primepi(math.isqrt(x))+1
assert rhs(100)==22

